export const fieldGuide=new Map([
  ["DOC-01",["صور أصلية مفهرسة حسب الغرفة والجدار والاتجاه، مع ربط المناطق الظاهرة بعناصر المسقط.","توضح سياق الفتحة أو العائق وتقترح عناصر ليراجعها الفني، وتكشف جدارًا لم يُصوَّر.","تُستخدم القياسات الموثقة المتاحة ويُطلب تصوير الوجه الناقص عند الحاجة إلى إثبات عنصر أو حسم اختلاف.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","عند بدء رفع غرفة أو توثيق تغيّر تشطيب أحد جدرانها."]],
  ["DOC-02",["دليل بصري مرتبط بمعرّف عنصر وصورة لسياقه، مع مرجع مقياس وموضعه عند توفره.","تساعد في تمييز المخرج من المحبس وتوثيق شكل البروز، وتحدد الموضع المطلوب قياسه مستقلًا.","تُسجّل الوظيفة أو المقاس المشكوك فيه للمراجعة. لا يتحول البعد الظاهر في الصورة وحده إلى مقاس قص.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","عند تحديد بروز أو فتحة أو توصيلة تحتاج لقطة مقرّبة ومرجع قياس."]],
  ["DOC-03",["مخطط مرجعي له إصدار ومقياس وتحويل إلى محاور الغرفة، مصنف قائمًا أو مقترحًا.","يبني مسقطًا أوليًا ويقارن المواقع والأبعاد فيه بالرفع الفعلي ليحدد ما تغير.","يستمر الرسم اليدوي من الرفع. أي تعارض يؤثر في قطعة يظل مفتوحًا حتى توثيق الحال المنفذ.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","عند توفر مخطط سابق أو تعارضه مع القياس في الزيارة."]],
  ["DOC-04",["نقاط ثلاثية الأبعاد مرتبطة بمرجع الغرفة، مع مناطق رصد وفجوات وقياسات تحقق.","يستخرج سطوحًا ومقاطع مبدئية ويكشف تعرّج الجدار أو اختلاف الأرضية عند موقع الخزانة.","يعوَّض المسح برفع يدوي. لا تُعتمد أبعاد منطقة محجوبة أو تطابقها ضعيف دون قياس مناسب.","٢ · رفع الغرفة والخدمات","—","عند استيراد مسح رقمي وربطه بنقطة أصل الغرفة."]],
  ["DOC-05",["قراءات أصلية تربط كل قيمة مشتقة بالأداة والطريقة والوقت ومرجع القياس.","يتحقق من التحويل والوحدة ويقارن دقة طريقة الرفع بمستوى الدقة الذي تحتاجه القطعة.","تبقى القراءة المسجلة متاحة. يُعاد القياس الحرج إذا تعذّر إثبات مصدره أو سماحيته.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","عند ربط أداة أو تثبيت قراءة يستند إليها بُعد حرج."]],
  ["DOC-06",["مسألة مفتوحة تربط العنصر المتأثر بالقيم المتعارضة ومصادرها والمسؤول عن حسمها.","تعرض للمراجع أثر كل احتمال وتعلّم القطع والقرارات التي تعتمد على نتيجة الحسم.","يمكن استكمال البدائل بفرضية معلنة. يتوقف الاعتماد المتأثر حتى اختيار قيمة موثقة وحفظ سبب القرار.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","عند اختلاف مصدرين أو حجب عنصر مؤثر، ثم عند حسمه قبل إصدار قطعته."]],
  ["SITE-01",["غرفة ذات معرّف وطابق ومرحلة تشطيب، ترتبط بها الزيارات ونسخ الرفع.","يختار مسح المطبخ الصحيح ويبيّن إن كان التصميم يستند إلى زيارة سبقت تغيير التشطيب.","تُحفظ الصور مؤقتًا. يُحسم رقم الغرفة والزيارة قبل دمج قياساتها أو إرسالها للتصنيع.","٢ · رفع الغرفة والخدمات","١ · فتح المشروع","عند بدء زيارة غرفة أو إضافة مطبخ آخر للمشروع."]],
  ["SITE-02",["نقطة أصل ومحاور ومنسوب صفر ووحدة، تُحوَّل إليها إحداثيات الصور والمخططات والقياسات.","يجمع موضع الصرف والنافذة والتعلية في المسقط نفسه ويحفظ معنى الارتفاع عن الأرضية النهائية.","تُحفظ القراءات في مراجعها الأصلية. يتوقف دمجها وفحص التعارضات المكانية حتى مطابقة المراجع.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","قبل ربط الصور والنقاط بمسقط الغرفة، وعند إعادة الرفع."]],
  ["SITE-03",["سلسلة معالم مرتبة لكل جدار واتجاه. بين المعالم مقاطع صافية وفتحات وخدمات وحدود صفوف، مع حفظ المنسوب والعمق عند تأثيرهما.","يجمع البرنامج المسافات المتعاقبة لتحديد المواضع، ويحتفظ بالأجزاء الصالحة كامتدادات منفصلة عند وجود انقطاع. ينتهي التوزيع عند حدّ الصف المحدد للمشروع.","يُرسم الجزء المقاس مبدئيًا. تُعلّق مطابقة الوحدات بالأضلاع المفتوحة أو غير المحسومة.","٢ · رفع الغرفة والخدمات","٤ · اختيار التوزيع","عند تعيين حدود تركيب الصف على جدار، أو استثناء جزء يختلف فيه صافي العمق أو الارتفاع."]],
  ["SITE-04",["قيود تحقق بين نقاط معلومة تحفظ الزاوية والقطر المقاسَين مستقلين عن أطوال الجدران.","يكشف ركنًا غير قائم أو مسقطًا لا يطابق القطر، ويعيد فحص دولاب الزاوية وحافة السطح.","تظهر الزاوية المفترضة على الرسم. إذا جاوز الفرق سماحية المشروع تُعاد قياسات الركن قبل قص القطع الملاصقة.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","عند إغلاق محيط الغرفة أو التحقق من ركن ستُفصّل عليه وحدات."]],
  ["SITE-05",["مقاطع عرضية لوجه الجدار عند مناسيب القاعدة والرخام والعلويات، تربط كل بروز بموضعه.","يحسب أصغر عمق متاح في منطقة الوحدة، ويحدد أين تتطلب الحافة تفصيلًا أو حشوة.","يُعرض الجدار التقريبي. تتأجل حافة الرخام أو الخزانة المحصورة التي تعتمد على شكل الجدار الحقيقي.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","عند قياس جدار على ارتفاعات الخزائن أو فحص تماس وحدة طويلة معه."]],
  ["SITE-06",["طبقات الجدار وسماكته وما هو معروف عن مادة التثبيت، مرتبطة بمصدر كل خاصية.","يبين عمق التجويف وردّة الفتحة ويعرض نقاط تعليق الوحدات للمراجعة وفق مادة الجدار.","يمكن توزيع الوحدات. يحتاج تثبيتها والمقاسات العابرة لسماكة الجدار إلى تحقق موضعي.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","إذا أثرت سماكة الجدار أو مادته في تجويف أو تثبيت."]],
  ["SITE-07",["سطح أرضي محدد الحدود، بمناسيب مقاسة عند نقاط الارتكاز والمداخل وحول البلاعات.","يحسب ارتفاع الفتحة فوق الأرض الفعلية وفروق الارتكاز، ويقارنها بمدى ضبط الأرجل المعتمدة.","يظهر المحيط دون منسوب دقيق. تبقى تسوية الوحدات وخلوص الأجهزة فوق المنطقة غير المقاسة قيد الفحص.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","عند تحديد مرجع الأرض وميلها، أو ظهور فرق عند موضع جهاز."]],
  ["SITE-08",["سطوح علوية متعددة المناسيب، مع كتل السقوطات وحيز فتح أغطية التفتيش.","يحد ارتفاع الخزائن الطويلة ويفحص حركة الدرف الرافعة ومرور الدكت تحت الجسور.","يمكن تخطيط الوحدات السفلية. ينتظر تفصيل النهايات العليا والقطع القريبة من السقوط رفع المنسوب.","٢ · رفع الغرفة والخدمات","٥ · تفصيل الهيكل وتثبيته","عندما يؤثر السقف في ارتفاع وحدة أو فتحها وكان الحيز الرأسي الصافي غير كافٍ لحسم القرار."]],
  ["SITE-09",["جسم ثابت بحدود أفقية ومنسوب سفلي وعلوي، مستقل عن الجدار الذي يتصل به.","يستبعد الخزائن التي تتداخل معه ويحدد موضع ردّة أو تفصيلة خاصة حيث يسمح المصنع.","يبقى الحيز المختلف عليه محجوزًا. يُقاس قبل اعتماد وحدة أو سطح يلامس حدوده.","٢ · رفع الغرفة والخدمات","٤ · اختيار التوزيع","عند وجود عمود أو جسر أو كتف يقتطع من حيز الخزانة."]],
  ["SITE-10",["حيز مجوف أو مغلق مع وجه دخول وفتحات صيانة، وحالة معرفة ما وراء الواجهة.","يميّز التجويف القابل للاستغلال من مجرى الخدمات المشغول ويختبر الوصول بعد وضع الوحدات.","تظل المنطقة تخصيصًا محتملًا. يحتاج استغلالها أو تغطية فتحتها إلى كشف أبعادها ووظيفتها.","٢ · رفع الغرفة والخدمات","٤ · اختيار التوزيع","عند رصد منور أو تجويف أو مسار خدمات داخل حدود المطبخ."]],
  ["SITE-11",["فتحة في جدار وجسم ضلفة يدور أو ينزلق مع مقبضه، إضافة إلى عرض المرور الصافي.","يفحص مواضع الثلاجة والجزيرة والأدراج على طول مسار الفتح والدخول.","يظهر موضع الباب التقريبي. تتأجل نتيجة المرور وفتح الأبواب المجاورة حتى تحديد الجهة والأبعاد.","٢ · رفع الغرفة والخدمات","٤ · اختيار التوزيع","إذا كانت فتحة الباب أو حركته تؤثر في نطاق مقترح ولم يكن أثرها ممثلًا في صافي القياس."]],
  ["SITE-12",["فتحة وإطار داخل جدار، لها جلسة وعمق وضلف ومقابض ذات مسارات حركة.","يختبر ارتفاع السطح والخلاط تحت الشباك وتعارض الوحدات العلوية مع فتحه.","تُعرض النافذة ضمن الواجهة. يظل وضع الخلاط أو الخزانة المتداخلة محتملًا حتى قياس الجلسة والحركة.","٢ · رفع الغرفة والخدمات","٥ · تفصيل الهيكل وتثبيته","عند تأثير الشباك في الصف العلوي أو السطح أو الحركة، وبالقدر الذي لا يحسمه نطاق التركيب الصافي. يسجل طلب الستارة لكل شباك، ويُحدّد حيز الستارة الباقية أو المطلوبة إن أثّر في التصميم."]],
  ["SITE-13",["حافة طولية أو عتبة عند منسوب معلوم، ببروز محلي وحالة إبقاء أو إزالة.","يحسب الارتداد الفعلي للقاعدة عند الجدار، ويختبر مرور الجهاز عند العتبة.","تُوزع الخزائن مبدئيًا. ينتظر قص الوزرة الملاصقة أو اعتماد مرور الجهاز قياس البروز.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","إذا أثرت النعلة أو الحافة في جسم الوحدة أو قاعدتها وكان أثرها غير مشمول في القياس الصافي."]],
  ["SITE-14",["حالة حالية وأخرى متوقعة لسطوح الجدران والأرضية والسقف، تربطهما سماكات التشطيب.","يعيد حساب العرض والارتفاع الصافيين بعد التبليط، ويحدد الأبعاد المطلوب رفعها مجددًا.","يستمر العرض بالقيم المفترضة المعلّمة. يُعلّق قص القطعة المحصورة حتى تثبيت البعد النهائي.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","عندما لم يكتمل البلاط أو سيتغيّر التشطيب بعد الزيارة."]],
  ["SITE-15",["جسم قائم له غلاف وحالة زمنية مثل إبقاء أو إزالة، مع تسجيل ما تحجبه رؤيته.","يحجز حيز الجسم الباقي ويتيح استكشاف بديل بعد الإزالة ويحدد موضع إعادة الرفع.","يحافظ على الجسم في نسخة الواقع. البديل المعتمد على إزالته يبقى مشروطًا بإقرار الإزالة والكشف.","٢ · رفع الغرفة والخدمات","٣ · احتياجات العميل وأجهزته","عند العثور على عنصر قائم، ثم عند تأكيد العميل الاحتفاظ به أو إزالته."]],
  ["SITE-16",["مساحات على وجه الجدار مصنفة حسب توثيق التدعيم أو حظر الحفر، وتقارن بمواضع المثبتات.","يبرز ثقب تعليق يقع في منطقة محظورة أو في موضع لم تتأكد صلاحيته، ويرفعه للمختص.","يمكن عرض الوحدة بمكانها. ينتظر اعتماد ثقوب التثبيت التحقق من المادة والخدمات المخفية.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","عند رصد تدعيم أو نطاق يمنع ثقبه، وعند اعتماد مواضع المثبتات."]],
  ["SITE-17",["بعد مرتبط بالقطع التي تعتمد عليه، وقراءتا تحقق ومجال سماح خاص بالقطعة.","يقارن القراءات ويمنح البعد حالة مؤكد أو يحتاج إعادة رفع، وتظهر على القطع التابعة.","يستمر العمل في القطع المستقلة. يبقى قص القطعة المعنية معلقًا إذا غاب التحقق المطلوب أو اختلفت القراءات.","٨ · اعتماد التنفيذ لدى المصنع","٢ · رفع الغرفة والخدمات","عند تجهيز أمر تصنيع يعتمد على قياس مخفي أو سابق للتشطيب."]],
  ["SITE-18",["محيط تنفيذي موثّق لحافة السطح ومواضع الوصلات والفتحات بعد تركيب القواعد.","يستبدل خط الجدار التقريبي بخط القالب عند تجهيز قطع السطح وفتحات الأجهزة.","يمكن إعداد تصور السطح وعرضه التقديري. يتأجل قص ما تتطلب طريقة توريده قالبًا نهائيًا.","٩ · التركيب والاستلام","٨ · اعتماد التنفيذ لدى المصنع","بعد تثبيت الوحدات وتسويتها، وقبل إصدار قصّ دفعة السطح."]],
  ["SITE-19",["مضلع فوق الأرضية بمناسيب معلومة وانقطاعات، تُقارن حدوده بمواضع أرجل كل جهاز أو وحدة.","يحسب صافي الارتفاع حتى أسفل الرخام من منسوب الارتكاز الفعلي، وينبه للأرجل الواقعة على جانبي الحافة.","يُعرض البديل مبدئيًا. يظل ارتفاع الفتحة أو انتظام الارتكاز غير محسوم قرب الحواف أو الانقطاعات غير المقاسة.","٢ · رفع الغرفة والخدمات","٥ · تفصيل الهيكل وتثبيته","عند وجود تعلية أو انقطاع فيها، ثم عند فحص ارتكاز وحدة أو جهاز."]],
  ["MEP-01",["نقطتا تغذية منفصلتان بمراكز وارتفاعات ونوع وصلات، ترتبط كل منهما بالحوض أو الجهاز.","يقيّم وصول التغذية إلى التجهيز المختار ويحدد مناطق فتح ظهر الخزانة أو أعمال النقل المحتملة.","يبقى توزيع الحوض اقتراحًا. ينتظر مسار التوصيل وفتحات الظهر تحديد النقاط واعتماد الفني.","٢ · رفع الغرفة والخدمات","٤ · اختيار التوزيع","عند تحديد مغذّي ماء، ثم عند اقتراح مكان حوض أو جهاز متصل به."]],
  ["MEP-02",["محبس مربوط بخط تغذية، يشغل حجماً وله مجال دوران للمقبض وحيز لوصول اليد.","يكشف رفًا أو درجًا يحجب العزل، فيُراجع ارتفاع الرف أو يُقترح باب صيانة.","يستمر تصميم الأجزاء الأخرى. يحتاج إغلاق الحيز حول المحبس إلى تأكيد موقعه وسهولة الوصول إليه.","٢ · رفع الغرفة والخدمات","٥ · تفصيل الهيكل وتثبيته","عند توثيق محبس يجب إبقاؤه متاحًا من داخل الخزانة أو أمامها."]],
  ["MEP-03",["مخرج معلوم الموضع والمنسوب والقطر، تربطه وصلات مقترحة بالحوض أو الجهاز وحيز السيفون.","يفحص تداخل السيفون والخرطوم مع الدرج ويحدد موضع فتحة الظهر ومسارًا يراجعه السباك.","يُعرض الحوض مبدئيًا. تؤجل فتحة الظهر وحسم مسار الصرف إذا غاب منسوب المخرج أو اختلفت وظيفته.","٢ · رفع الغرفة والخدمات","٤ · اختيار التوزيع","عند تحديد مخرج الصرف، ثم عند مقارنة مواقع الحوض والأجهزة."]],
  ["MEP-04",["مضلع غطاء في سطح الأرض، له منسوب وحدود وصول وحيز لرفع الغطاء وتنظيفه.","يكشف تغطية البلاعة بقاعدة أو جزيرة أو تعلية ويقارن منسوبها بالنقاط المقاسة حولها.","لا يُجزم بإمكان تنظيفها. ينتظر اعتماد قطعة ثابتة فوق المنطقة تحديد حدود الغطاء وطريقة رفعه.","٢ · رفع الغرفة والخدمات","٤ · اختيار التوزيع","عند وجود بلاعة أرضية أو مصرف يحتاج غطاؤه إلى مساحة وصول."]],
  ["MEP-05",["مسار مقسم إلى أجزاء ذات قطر أو غلاف، يُسجّل مصدر كل جزء ودرجة التحقق منه.","يفحص اصطدام الظهر أو الدرج بما هو ظاهر ويعرض المخاطر الموثقة عند مواقع الحفر.","تُفحَص الأجزاء المرصودة. تبقى امتدادات المسار غير المرصودة مجهولة ويُتحقق من مواضع التثبيت المتأثرة.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","عند رصد أنبوب ظاهر أو ورود مخطط عن مسار مخفي يتأثر بالتثبيت."]],
  ["MEP-06",["جهاز بحجمه ووصلاته ومساحة فكه وصيانته، مع متطلبات التهوية المرتبطة بالموديل.","يحفظ حيز السخان وخدمته ولو اختار العميل إبقاءه ظاهرًا. عند طلب الغطاء، يفحص توافقه مع تعليمات الموديل والفتحة اللازمة للوصول والفك قبل اعتماده.","يُحجز الحيز المشاهد. يبقى تغليفه أو نقله معلقًا حتى تأكيد الموديل ومتطلبات المختص.","٢ · رفع الغرفة والخدمات","٥ · تفصيل الهيكل وتثبيته","عند وجود سخان أو موضع تجهيز له يلزم الوصول إليه بعد التركيب."]],
  ["MEP-07",["أجسام صغيرة ووصلات داخل خزانة الحوض، مع حيّز إخراج شمعة الفلتر أو الخزان.","يحسب المساحة المتبقية للتخزين ويختبر إمكان تبديل الفلتر دون فك الخزانة.","يمكن تخطيط وحدة الحوض. ينتظر تثبيت الرف أو الدرج الداخلي قرب الفلتر تأكيد الحجم ومسار الخدمة.","٢ · رفع الغرفة والخدمات","٥ · تفصيل الهيكل وتثبيته","عند وجود فلتر أو مضخة أو خزان، ثم عند تفصيل حيز صيانته."]],
  ["MEP-08",["نقطة تغذية ومحبس ومسار موثّق ومساحات خدمة معتمدة، مرتبطة بموديل جهاز يعمل بالغاز.","يقارن مواقع الجهاز المقترحة بالخط والتوصيل وإمكان الوصول للمحبس ويحدّد ما يحتاج مراجعة مختص.","إذا لم يُطلب غاز يُسجَّل عدم الانطباق. عند طلبه تظل التوصيلة أو التعديلات مشروطة بتحقق المختص.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","عند ظهور خط أو محبس غاز، ويؤكد المختص التفاصيل المؤثرة."]],
  ["MEP-09",["مخرج على سطح محدد، له موضع ونوع وعدد ومستهلك مقصود، وحالة قائم أو مقترح.","يفحص احتجاب المقبس بخزانة، وإمكان توصيل الجهاز في موضعه أو الحاجة إلى نقطة إضافية.","يبقى الجهاز قابلًا للعرض. يتأجل تأكيد توصيله أو قص الفتحة حول العلبة حتى مراجعة الموقع والنوع.","٢ · رفع الغرفة والخدمات","٤ · اختيار التوزيع","عند تحديد مقبس أو تغذية مباشرة على جدار أو أرض أو جزيرة."]],
  ["MEP-10",["ربط بين الدائرة والمخارج والأجهزة، بقيم موثقة للكهرباء ومتطلبات كل موديل.","يبرز اختلاف جهد أو متطلب دائرة أو حمل يستدعي مراجعة الكهربائي قبل توصيل الجهاز.","يمكن اعتماد الحيز الهندسي مستقلاً. تظل ملاءمة التغذية والتوصيل غير مؤكدة إلى حين مراجعة الكهربائي.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","إذا احتاج جهاز لدائرة محددة، وتُستكمل القدرة الفعلية من المختص."]],
  ["MEP-11",["لوحة على جدار ذات حدود ومجال وصول، ويربط كل زر بمجموعة إنارة أو جهاز.","يحدد إن كانت خزانة طويلة ستخفي تشغيل الإنارة، ويبيّن من أي مدخل يصل المستخدم إلى المفتاح.","تُظهر الخزانة مبدئيًا. ينتظر اعتماد التغطية أو النقل توثيق موضع اللوحة ووظيفة أزرارها.","٢ · رفع الغرفة والخدمات","٥ · تفصيل الهيكل وتثبيته","عند تسجيل مفتاح أو جهاز تحكم قبل أن تغطيه واجهة أو جهاز."]],
  ["MEP-12",["فتحة خدمة وغطاء ذو حركة وحدود وصول مرتبطة بنوع اللوحة وموقعها.","يكشف تعارض خزانة أو رف مع فتح الغطاء أو صيانة العداد، ويحدد المنطقة التي يجب إبقاؤها متاحة.","يُحجز موضع العنصر الظاهر. يمنع حسم القطعة المواجهة قبل معرفة فتحة الخدمة وحدود الوصول.","٢ · رفع الغرفة والخدمات","٥ · تفصيل الهيكل وتثبيته","عند وجود لوحة أو عداد أو فتحة تفتيش تحتاج مجال فتح وصيانة."]],
  ["MEP-13",["جهاز بنظام طرد أو تدوير، ومسار دكت بمقطع ونهاية لطرد الهواء عند انطباقه.","يفحص مرور الدكت داخل العلويات وحاجته لفتحة أو كسوة، ويقارن مساره بقيود الموديل.","يمكن عرض الشفاط. تبقى ثقوب الدكت وتفاصيل الخزانة المتأثرة مشروطة بحسم نظام التشغيل والمسار.","٢ · رفع الغرفة والخدمات","٤ · اختيار التوزيع","عند وجود فتحة شفط أو مسار دكت يؤثر في موضع الموقد أو العلويات."]],
  ["MEP-14",["وحدة ومنافذ هواء ومسار تكثف وأنابيب، مع حيّز فتح الفلتر للصيانة.","يفحص تداخل الوحدات العلوية مع مخرج الهواء أو فتحة الفلتر أو خط التكثف.","يستمر توزيع القطع البعيدة. يتطلب تغطية الوحدة أو البناء قرب منافذها مراجعة بياناتها الفعلية.","٢ · رفع الغرفة والخدمات","٤ · اختيار التوزيع","عند رصد وحدة تكييف أو فتحة دفع أو رجوع أو صرف تكاثف."]],
  ["MEP-15",["مصابيح محددة المواضع والمناسيب، بأحجام وخصائص ضوئية ومجموعات تحكم.","يربط الإضاءة بالمشهد ويفحص اصطدام باب علوي مرفوع بمصباح معلّق.","يمكن عرض إضاءة تقريبية. يتوقف التحقق من الاصطدام أو مطابقة الضوء الفعلي على مواصفات المصباح وموقعه.","٢ · رفع الغرفة والخدمات","٥ · تفصيل الهيكل وتثبيته","عند رفع إنارة قائمة أو تحديد تأثير وحدة طويلة في الضوء."]],
  ["MEP-16",["شريط أو كشاف مرتبط بوحدة، بطول ومسار سلك ومحوّل وحساس يمكن الوصول إليها.","ينتج أطوال الإنارة ومواضع مجاريها وتجهيزات تشغيلها، ويفحص إتاحة استبدال المحوّل.","تبقى الإضاءة اختيارية في العرض. ينتظر تفريز المجرى وطلب القطع تحديد الموديل ومكان التغذية.","٥ · تفصيل الهيكل وتثبيته","٨ · اعتماد التنفيذ لدى المصنع","عندما يختار العميل إضاءة داخلية أو أسفل الخزائن، فتُراجع التغذية والتمديد."]],
  ["MEP-17",["نافذة باتجاه معلوم وعوائق ظل وسيناريو عرض بوقت تقريبي وخصائص إضاءة مرغوبة.","يضبط اتجاه الظلال ومظهر الخامات، ويتيح مقارنة الواجهة في النهار ومع الإنارة الداخلية.","يُعرض المشهد بإضاءة افتراضية معلنة. يظل الحكم على مطابقة اللون والظل للموقع تقريبيًا.","٢ · رفع الغرفة والخدمات","٥ · تفصيل الهيكل وتثبيته","عند إعداد عرض واقعي يحتاج مصدر ضوء أو توثيقًا نهاريًا للمطبخ."]],
  ["MEP-18",["عنصر قائم أو مخطط له، بموضع وغلاف خدمة ومتطلبات تغطية يثبتها المختص.","يشير إلى وحدة أو كسوة قد تعيق الوصول أو تتعارض مع الحدود المعتمدة.","تُخطط المساحات البعيدة. تبقى التعديلات التي قد تؤثر في العنصر أو تغطيته قيد مراجعة المختص.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","عند رصد كاشف أو رشاش أو نقطة إنذار قد تحجبها وحدة."]],
  ["MEP-19",["نقاط تحكم وبيانات تربط الحساس أو المشغل بوحدة التحكم والتغذية ومسار الكابل.","يحدد الحاجة إلى مخرج كابل أو حيّز لوحدة التحكم، ويربط الحساس بالباب أو الدرج المقصود.","يعمل التصميم اليدوي للقطعة. يتأجل اعتماد وظيفة التحكم وتمديد كابلها حتى تحديد النظام والتغذية.","٢ · رفع الغرفة والخدمات","٥ · تفصيل الهيكل وتثبيته","عند وجود تغذية منخفضة الجهد أو تحكم ذكي مطلوب للخزائن أو الأجهزة."]],
  ["MEP-20",["نسختان لموضع النقطة، قائم ومقترح، مع إذن النقل ومسؤوله وحالة التنفيذ والتحقق.","يفصل بديلًا صالحًا على الوضع القائم عن بديل يحتاج نقلًا، ويدرج الأعمال المعتمدة في نطاق المشروع.","يبقى البديل المشروط ظاهرًا. لا يُعتمد حفر أو فتحة نهائية وفق نقطة مقترحة قبل تحقق النقل أو إقرار المسؤول لتسلسل العمل.","٤ · اختيار التوزيع","٧ · مراجعة العرض واعتماد العميل","عندما يتطلب أحد التوزيعات نقل خدمة، ويُبيّن نطاق العمل وكلفته قبل الاعتماد."]],
  ["PRJ-01",["يربط رقم المشروع ومعرّف المطبخ كل قياس وصورة وجهاز بنسخة الغرفة الصحيحة.","يفصل مطبخ التحضير عن المطبخ الرئيسي عند تجميع العناصر وإصدار الرسومات.","تُعلّق الصور أو القياسات مجهولة الغرفة إلى أن تُنسب إلى المكان الصحيح.","١ · فتح المشروع","—","عند إنشاء ملف جديد أو إضافة مطبخ إلى مشروع قائم."]],
  ["PRJ-02",["يسند لكل نوع قرار الشخص المخوّل به في المشروع ووسيلة الرجوع إليه.","يوجّه طلب اعتماد السعر أو نقل نقطة الماء إلى صاحب الصلاحية، ويسجّل من أجاز التغيير.","تُحفظ الخيارات كمسودات وتبقى الموافقة المعنية معلّقة حتى يتحدد صاحبها.","١ · فتح المشروع","٧ · مراجعة العرض واعتماد العميل","عند تحديد من يتواصل معه المندوب ومن يملك اعتماد العرض."]],
  ["PRJ-03",["يصنّف كل عمل أو توريد كمشمول أو مستثنى أو يحتاج إلى اتفاق، مع الطرف المنفّذ.","يفصل مثلًا تكلفة تصنيع فتحة الفرن عن ثمن الفرن الذي يورده العميل.","يُعرض البند غير المحسوم منفصلًا، ويؤجّل اعتماد إجمالي العرض حتى يتضح نطاقه.","١ · فتح المشروع","٧ · مراجعة العرض واعتماد العميل","عند تحديد نطاق الأعمال، ثم عند تثبيت المشمول والمستثنى في العرض."]],
  ["PRJ-04",["يربط أحداث القياس والتوريد والتركيب بتواريخ مستهدفة أو مؤكدة، وبما يجب إنجازه قبلها.","يكشف أن وصول الحوض بعد موعد إعداد قالب السطح يستلزم تغيير ترتيب الموعدين.","يستمر التصميم وتظهر المواعيد غير المؤكدة كمواعيد تقديرية عند التخطيط للتسليم.","١ · فتح المشروع","٧ · مراجعة العرض واعتماد العميل","عند وجود موعد للزيارة أو التشطيب أو حاجة العميل إلى تسليم محدد."]],
  ["PRJ-05",["يحفظ المبلغ وعُملته وما يشمله وطريقة احتساب الضريبة، ويميّز السقف الملزم عن النطاق المفضل.","يقارن تكلفة كل بديل بالميزانية على أساس البنود نفسها، ويعرض مقدار الفرق.","يمكن تسعير البدائل من الكتالوج، ويؤجّل الحكم على ملاءمتها للميزانية حتى تتحدد.","٣ · احتياجات العميل وأجهزته","٧ · مراجعة العرض واعتماد العميل","عند تحديد نطاق إنفاق يوجّه البدائل، ثم عند مقارنة السعر النهائي به."]],
  ["PRJ-06",["يربط بكل عنصر قائم إجراءً مقترحًا وحالة الموافقة عليه، ويحفظ موضعه الحالي والمقترح منفصلين.","يثبّت الحوض الباقي في بديل، ويبيّن أعمال الفك والنقل في بديل وافق عليه العميل.","يظل العنصر في مخطط الوضع القائم، ويُعلّم البديل المعتمد على نقله للمراجعة.","٣ · احتياجات العميل وأجهزته","٢ · رفع الغرفة والخدمات","عند ذكر العميل أجهزة أو خزائن أو تمديدات ستبقى أو ستتغير."]],
  ["PRJ-07",["يسجّل القفل على خاصية محددة، مثل الاستخدام أو الموضع، مع صاحب القرار وإصدار اعتماده.","يعيد توليد توزيع الخزائن مع إبقاء موقع درج الرز إذا ثُبّت، أو يسمح بنقله إذا ثُبّت استخدامه فقط.","يُعرض التفضيل غير المحسوم للمقارنة. وإذا تعارض شرطان مثبتان يُطلب تعديل أحدهما من صاحبه.","٣ · احتياجات العميل وأجهزته","٧ · مراجعة العرض واعتماد العميل","عند تسجيل أي رغبة، ثم عند مراجعة ما ثبّته العميل قبل اعتماد النسخة."]],
  ["PRJ-08",["يحفظ ترتيب أهداف العميل ويربط كل هدف بمؤشر، مثل التكلفة أو طول سطح التحضير المتصل.","يرتّب الحلول الممكنة بحسب الأولوية المعتمدة مع إظهار الفرق الفعلي بين البدائل.","تبقى البدائل الممكنة متاحة للمقارنة ويختار العميل ترتيب الأولويات متى شاء.","٣ · احتياجات العميل وأجهزته","٤ · اختيار التوزيع","عندما يوازن العميل بين التخزين وسطح التحضير والميزانية أو الحركة."]],
  ["PRJ-09",["يربط الجزء المحدد في الصورة بالصفة المقصودة، ويربط التشطيب المرشّح بعينة ورمز كتالوج.","يقترح واجهات قريبة من المرجع ويحدد أي عينة ينبغي عرضها لاعتماد اللون أو الملمس.","يمكن استكمال التوزيع. تبقى الخامة المرشّحة مفتوحة إلى حين اختيار عينة بعينها.","٣ · احتياجات العميل وأجهزته","٦ · اختيار المواد والخامات والألوان","عند إرفاق صور ذوق أو أمثلة أولية، ثم بعد تثبيت الهيكل لمطابقتها بعينات وأكواد فعلية يختارها العميل."]],
  ["USE-01",["يمثّل الأشخاص بحسب سيناريو الاستخدام وتزامن المهام، مثل التحضير والطبخ في الوقت نفسه.","يقارن بدائل محطات العمل بحسب إمكان استخدام شخصين لهما وتداخل مساراتهما.","تُعرض ترتيبات أولية، وتبقى ملاءمة الاستعمال المتزامن بحاجة إلى مراجعة مع الأسرة.","٣ · احتياجات العميل وأجهزته","٤ · اختيار التوزيع","عند تحديد من يستخدم المطبخ والأنشطة التي يجب أن يخدمها."]],
  ["USE-02",["يمثّل كل رحلة بسلسلة مواضع، مثل باب المقاضي ثم الثلاجة ثم خزانة المؤن.","يقارن طول مسار الوصول وتقاطعه مع باب أو جهاز مفتوح عند ترتيب نقاط التخزين والتحضير.","يظل المسقط قابلًا للتعديل، ويؤجّل تفضيل بديل بسبب مسار لم يحدده العميل.","٣ · احتياجات العميل وأجهزته","٤ · اختيار التوزيع","إذا كان مسار التسوق أو التحضير أو التقديم يؤثر في التوزيع."]],
  ["USE-03",["يربط مدى الوصول وحيز الاقتراب وجهة الفتح بالمستخدم ومحطة العمل المحددة.","يتحقق من إمكان بلوغ المقبض أو الرف، ويرجّح موضعًا أسهل أو آلية فتح مختلفة.","تُحفظ الأبعاد المبدئية ويُطلب اختبار الوصول للعنصر الذي يتوقف قبوله على راحة المستخدم.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","عند وجود متطلبات وصول أو ارتفاعات مفضلة تُختبر على النموذج."]],
  ["USE-04",["يجمع الأجهزة والأدوات ومساحة العمل والخدمات اللازمة تحت معرّف محطة مثل ركن القهوة.","يركّب بديلًا يجمع الماكينة والفناجين والتعبئة ويُبقي الحيز الذي اختاره العميل متاحًا.","إن لم تُطلب محطة خاصة يستمر التوزيع العام. وإن طُلبت وبقيت أجهزتها مجهولة يُحجز موضع مبدئي.","٣ · احتياجات العميل وأجهزته","٤ · اختيار التوزيع","عند طلب ركن قهوة أو عجن أو تجهيز أو أي محطة خاصة."]],
  ["USE-05",["يمثّل طلبًا بطول متصل وموقع مفضل، وتُستبعد من المساحة المتاحة فتحات الحوض والطبخ والأجهزة الدائمة.","يقارن أطول جزء قابل للاستخدام بطلب العميل ويعرض مقدار النقص عند استبداله بخزانة طويلة.","يمكن عرض الأطوال المتاحة في كل بديل، ويبقى تقييم كفايتها متروكًا للعميل.","٣ · احتياجات العميل وأجهزته","٤ · اختيار التوزيع","عندما يطلب العميل طولًا أو موقعًا لسطح تحضير متصل."]],
  ["USE-06",["يمثّل كل غرض بأبعاده عند التخزين ووضعه واتجاه إخراجه وعدده ووزنه إن عُرف.","يقارن أبعاد الغرض بفتحة الدخول والحيز الداخلي، ويحسب الحمل المحتمل على الرف أو الدرج.","يُحفظ الغرض في قائمة الاحتياجات ويؤجل تأكيد احتوائه حتى قياس البعد أو الوزن المؤثر.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","عند وجود غرض كبير أو غير معتاد يجب قياسه قبل تخصيص مكانه."]],
  ["USE-07",["يصنّف الأغراض حسب تكرار الاستعمال ويحدد الأزواج التي يريد العميل جمعها أو فصلها.","يرجّح التخزين الأقرب والأسهل وصولًا للأغراض اليومية ويجمع أدوات المهمة الواحدة.","تظل الأغراض قابلة للتوزيع، ويُترك ترتيبها الداخلي مفتوحًا إذا لم يحدد العميل تفضيلًا.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","عند تعيين أغراض يومية أو مجموعات يريد العميل إبقاءها متجاورة."]],
  ["USE-08",["يمثّل كل نوع مؤن بوزن ومعبّأ محدد، ويربط الطلب بأبعاد الكيس أو بسعة الحافظة أو موديل العيّاشة.","يفحص اتساع الدرج والحمل المتحرك والوصول للتعبئة. عند اختيار عيّاشة يفحص فتحتها ويضيف موديلها للعرض.","يبقى طلب التخزين محفوظًا. كمية الأرز وحدها لا تكفي لحسم أبعاد الكيس أو موديل الحافظة أو السكة.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","عند طلب تخزين الأرز أو المؤن، ثم عند تجربة الكيس أو الحافظة أو العيّاشة."]],
  ["USE-09",["يربط قطعة مرجعية كبيرة بوضعية تخزينها وغلاف أبعادها مع الغطاء والمقبض.","يختبر دخول الدلّة قائمة أو الصينية رأسيًا ويضبط الارتفاع الصافي ومكان الفاصل وفق الاختيار.","يستمر تصميم الواجهة، ويُترك تقسيم المقصورة المخصصة مفتوحًا إلى أن تُقاس القطعة المرجعية.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","عند ذكر قدر أو دلّة أو صينية مؤثرة، ثم عند التحقق من فتحة إخراجها."]],
  ["USE-10",["يربط عدد المقاعد ومقاس الكرسي وحدود سحبه بوجه الطاولة أو الجزيرة المختار.","يحسب المقاعد التي تستوعبها الجهة ويفحص تقاطع حيز الجلوس مع الممر وفتح الوحدات.","يمكن عرض جزيرة بلا مقاعد، أو إبقاء عدد المقاعد المقترح مؤقتًا حتى تُراجع الكراسي المختارة.","٣ · احتياجات العميل وأجهزته","٤ · اختيار التوزيع","عند طلب جلوس أو تقديم ضيافة على الجزيرة أو طرف السطح."]],
  ["USE-11",["يربط عدد الحاويات وسعاتها وطريقة إخراجها بموضع الاستخدام وبحيز السحب أو الرفع.","يختار منظمات تناسب الفرز المطلوب ويتحقق من إمكان إخراج الحاوية دون اعتراض السيفون أو الباب.","يبقى موضع قابل للتجهيز، ويؤجّل اختيار موديل الحاويات وتسعيره إلى حين تحديد نظام الفرز.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","عند طلب فرز النفايات أو محطة تنظيف ذات حاويات وتجهيزات خاصة."]],
  ["USE-12",["يربط معرّف الدرج بطلب العميل المكتوب أو المختار، ويفصل تثبيت الاستخدام عن تثبيت موضعه.","يحافظ على وظيفة الدرج عند إعادة التوزيع ويفحص أن الدرج البديل يلبّي الطلب المقيد.","عند تعارض التخصيص مع المقاس يعرض بدائل ويحفظ الاختيار المعتمد حتى يجيز العميل تعديله.","٥ · تفصيل الهيكل وتثبيته","٣ · احتياجات العميل وأجهزته","عندما يفتح العميل وحدة ويخصص درجًا، أو يحين إسناد حاجة سُجلت سابقًا."]],
  ["USE-13",["يمثّل مواضع الفواصل والرفوف والحاويات داخل الحجم الصافي للوحدة، مع حركة رفعها أو سحبها.","يعيد حساب مقاسات المقصورات وقائمة الفواصل ويختبر إمكان إدخال الحاوية وإخراجها.","تُعتمد الحدود الخارجية مستقلّة، وتبقى الفواصل أو الثقوب المرتبطة بحاوية مجهولة غير محسومة.","٥ · تفصيل الهيكل وتثبيته","٣ · احتياجات العميل وأجهزته","عند تجربة تقسيم داخل درج أو تخصيص حيز لحافظة يملكها العميل."]],
  ["USE-14",["يسند للواجهة نمط الحركة ومحورها واتجاهها والمقبض، ويربطها باختيارات الكتالوج المؤهلة.","يولّد مسار الفتح ويفحص اصطدامه بالجوار ويحدد المفصل أو السكة المتوافقين.","يبقى حجم الخزانة قابلًا للتخطيط، ويتأجل اعتماد إكسسوار الفتح وثقوبه إذا لم تُحسم الآلية.","٥ · تفصيل الهيكل وتثبيته","٦ · اختيار المواد والخامات والألوان","عند تثبيت تقسيم الدرف وطرق فتحها على الهيكل، ثم عند اختيار تشطيب الواجهات المثبّتة."]],
  ["USE-15",["يربط كل سطح ظاهر بعينة خامة واتجاه نقش، مع علاقات تطابق بين الواجهات المطلوبة.","يحدّث المنظور وسعر الأجزاء، ويراعي اتجاه الخامة عند إعداد قائمة القطع إذا كان اتجاهها مؤثرًا.","يمكن عرض لون تقريبي. يُعلّق طلب الخامة أو قص القطع المتطابقة حتى اعتماد العينة والاتجاه.","٦ · اختيار المواد والخامات والألوان","٧ · مراجعة العرض واعتماد العميل","بعد تثبيت الهيكل، عند تعيين مادة أو ملمس أو لون لنطاق أو جزء، ثم مراجعة الاختيارات مع العرض المالي. يشمل لون وخامة ستارة الشباك إذا طلبها العميل."]],
  ["USE-16",["يمثّل الحيز المطلوب مستقبلًا كمساحة محجوزة، مع خاصية تحدد ما يمكن ملؤه مؤقتًا.","يستبعد الوحدات الدائمة من الحيز المثبت ويقترح رفوفًا قابلة للفك عند السماح بها.","إذا لم يطلب العميل توسعة مستقبلية يُستكمل التصميم الحالي، ويظهر الحجز غير المحسوم كخيار.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","إذا أراد العميل احتياطيًا لجهاز مستقبلي أو تقسيمًا قابلًا للتغيير."]],
  ["EQP-01",["يمنح كل جهاز معرّفًا ويصله بموديله المحلي وحالة اختياره والجهة التي ستورّده.","ينشئ موضعًا لكل جهاز ويمنع شراء جهاز يورده العميل ضمن قائمة مشتريات المصنع.","تُحجز مساحة تقديرية للجهاز غير المحدد، وتظل فتحة التصنيع المرتبطة به غير معتمدة.","٣ · احتياجات العميل وأجهزته","٨ · اعتماد التنفيذ لدى المصنع","عند جرد الأجهزة الموجودة أو المرغوبة، ثم عند تثبيت الموديلات المؤثرة."]],
  ["EQP-02",["يخزن جسم الجهاز وفتحة التركيب وخلوص الموديل كأبعاد منفصلة مرتبطة بمرجع التركيب.","يقارن الفتحة المطلوبة بالحيز الصافي عند موضع الجهاز، ويظهر فرق العرض أو العمق أو الارتفاع.","تُستخدم أبعاد الجسم في العرض الأولي، ويُؤجّل إقرار الفتحة حتى مراجعة متطلبات الموديل.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","عند اختيار الموديل أو توفر دليله، ثم عند احتساب فتحة دمجه."]],
  ["EQP-03",["يبني مسار الباب أو الصينية وحيز السحب والصيانة من وضع الجهاز ومحاوره وأبعاد الموديل.","يفحص تقاطع الحركة مع مقبض أو جدار ويكشف ما إذا كان تبديل الفلتر أو سحب الجهاز متاحًا.","قد يجتاز الجهاز اختبار الأبعاد الساكنة، ويظل فتحه أو إخراجه للصيانة بحاجة إلى تحقق.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","عند تسجيل جهاز له باب أو درج أو مسار إزالة تتطلبه صيانته."]],
  ["EQP-04",["يربط منافذ الجهاز ومتطلباته المحددة في دليله بنقاط الخدمة المقاسة بالموقع ومسارات الوصول إليها.","يكشف نقص نقطة أو عدم تطابق موضعها أو نوعها، ويعرض أثر نقلها إذا سمح العميل والفني.","يوضح أي طرف غير معلوم، مثل قدرة الدائرة أو طول الوصلة، ويُترك توافق التوصيل للمختص.","٣ · احتياجات العميل وأجهزته","٢ · رفع الغرفة والخدمات","عند اختيار جهاز يتطلب توصيلات، ثم عند مطابقتها بتجهيز الموقع."]],
  ["EQP-05",["يمثّل تجويف الثلاجة وأبوابها وأدراجها وفتحات تهويتها ووصلة الماء عند طلبها في الموديل.","يفحص هل يفتح الباب بما يسمح بسحب الأدراج قرب الجدار ويراجع تجاويف التهوية والماء المطلوبة.","تُحجز كتلة للعرض، ولا تُحسم جوانب التجويف أو جهة الفتح حتى تحديد الموديل أو فحص الجهاز.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","عند إضافة ثلاجة أو فريزر وفحص حيز دوران الباب وسحب الأدراج."]],
  ["EQP-06",["يربط الفرن بموضع تركيبه في عمود أو تحت السطح أو على الأرض، وبالدعامة والفتحة ومسار الباب.","يضبط الرف الحامل وفتحة التهوية، ويفحص أن الباب المفتوح لا يحجب الممر أو يصطدم بمقبض مجاور.","يبقى مركز الطهي مقترحًا، ويؤجَّل قص تجويف الفرن ودعامته إلى حين مراجعة دليل التركيب.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","عند إضافة فرن أو جهاز طبخ، ثم عند تفصيل موضع الدعامة والفتحة."]],
  ["EQP-07",["يربط حدود فتحة القص واتجاه الموقد وامتداده تحت الرخام ومصدر الطاقة بالسطح والوحدة السفلية.","يتحقق من توافق الفتحة مع مقطع السطح وموضع الدرج تحتها ويحدد تعارضات الخلوص أو الطاقة.","يظل الموقد عنصرًا مبدئيًا في المنظور ويُحجب اعتماد فتحة السطح حتى وصول قالب الموديل.","٣ · احتياجات العميل وأجهزته","٨ · اعتماد التنفيذ لدى المصنع","عند اختيار سطح طبخ، ثم عند مطابقة رسم فتحة القص مع الموديل."]],
  ["EQP-08",["يربط شكل الشفاط وارتفاعه المرجعي ونوع الطرد واتجاه مخرجه بموقع الموقد والدكت المقاس.","يتحقق من تناسب الشفاط مع الوحدة العلوية وإمكان ربطه بطرد فعلي أو تجهيزه للتدوير المعتمد.","إذا غاب مسار الطرد أو نوع النظام يبقى حل الشفط معلّقًا، ويستمر تخطيط الوحدات المستقلة عنه.","٣ · احتياجات العميل وأجهزته","٤ · اختيار التوزيع","عند إضافة شفاط، ثم عند ربط الموقد بالدكت أو نظام التدوير المختار."]],
  ["EQP-09",["يمثّل الجهاز وإطار الدمج والتهوية ومسار الباب وارتفاع التشغيل المطلوب ضمن الوحدة.","يحدد ارتفاع الرف وفتحة الواجهة ويفحص وصول المستخدم وإمكان إخراج الأواني الساخنة.","يُعرض موضع تقريبي ويُؤجّل اعتماد إطار الدمج وفتحة الواجهة حتى التحقق من الموديل.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","عند وضع ميكروويف أو جهاز مدمج إضافي داخل وحدة مخصصة."]],
  ["EQP-10",["يربط فتحة موديل الغسالة ومنسوب ارتكازها بموقعها بين الخزائن، ويمثّل الدرفة والسلة عند الفتح.","يحسِب الارتفاع حتى أسفل الرخام ويكشف تعارض الدرفة مع التعلية أو الوزرة وباب خزانة مجاورة.","إذا غاب منسوب أرضية موضعها أو دليل الموديل تبقى صلاحية الفتحة والدرفة بحاجة إلى تحقق.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","عند إضافة غسالة صحون، ثم عند اختبار الباب والارتفاع والتعلية."]],
  ["EQP-11",["يصف وضع كل جهاز وطريقة فتحه وخدماته، ويربط الجهازين بطقم التكديس المحدد إذا اختير التكديس.","يفحص فراغ الغطاء العلوي أو الباب الأمامي وإمكان التهوية والصيانة وتوافق طقم التكديس.","يمكن عرض الجهازين منفصلين. يبقى التكديس أو الإغلاق داخل خزانة معلقًا حتى تتوفر بيانات التركيب.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","عند وجود غسالة ملابس أو مجفف ضمن نطاق المطبخ."]],
  ["EQP-12",["يمثّل مساحة قاعدة كل جهاز وحيزه أثناء الفتح أو التعبئة، ويفرّق بين موضع التخزين وموضع التشغيل.","يحسب سطح التحضير الذي يبقى متصلًا بعد وضع الأجهزة، ويفحص فراغ فتح الغطاء والوصول إلى فيش مناسب.","تظل مساحة التشغيل المطلوبة تقديرية، ويُستكمل فحصها عندما يحدد العميل الأجهزة التي ستبقى على السطح.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","إذا كان جهاز سيبقى على السطح أو يحتاج محطة تخزين واستخدام مخصصة."]],
  ["EQP-13",["يربط الحوض ونوع تثبيته وقالب قصه وحجمه أسفل الرخام بالخزانة ومسار الصرف.","يتحقق من اتساع الخزانة والدعم والتداخل مع جوانبها، ويجهّز فتحة السطح واتجاهها للمراجعة.","يمكن اقتراح خزانة للحوض. يتوقف قص السطح عند فقد القالب المطابق أو تغيير الحوض.","٣ · احتياجات العميل وأجهزته","٨ · اعتماد التنفيذ لدى المصنع","عند تعيين حوض، ثم قبل قص فتحة السطح أو تشكيل دعامة الحوض."]],
  ["EQP-14",["يسند لكل ملحق فتحة ومركزًا وقطرًا، ويمثل ارتفاع الخلاط ودورانه ومسار خرطومه.","يفحص تعارض الخلاط مع ضلفة الشباك ويعطي عدد ثقوب السطح ومواقعها بعد الاعتماد.","عند غياب موديل الخلاط تبقى حركة الشباك والثقوب ذات العلاقة معلقة، ويمكن مراجعة موضع الحوض نفسه.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","عند تحديد خلاط أو موزع إضافي وفحص حركته أمام الشباك."]],
  ["EQP-15",["يمثّل المصيدة والفلتر والسخان والتمديدات كأحجام داخلية، ويحتفظ بحيز فك الفلتر أو استبداله.","يحسب المساحة المتبقية لسلة التنظيف أو النفايات ويفحص اصطدامها بالسيفون عند السحب.","لا تُحتسب المنطقة المخفية تخزينًا شاغرًا مؤكّدًا، ويُراجع ترتيب المنظمات بعد توثيق المكونات.","٥ · تفصيل الهيكل وتثبيته","٣ · احتياجات العميل وأجهزته","عند تفصيل وحدة الحوض حول السيفون والفلتر وأغراض التخزين المطلوبة."]],
  ["EQP-16",["ينشئ عنصرًا مخصصًا بحدود الجسم والفتحة والحركة ومنافذ الخدمة، ويربطه بوثيقة مستقلة.","يختبر الجهاز ضمن التوزيع نفسه ويضيف تكلفة التوريد إن كانت ضمن العقد ومعلومة.","يبقى الجهاز بندًا مخصصًا مؤقتًا، وتُعلّق فقط الفتحة والتوصيلات التي تعتمد على بياناته الناقصة.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","عند إضافة جهاز خاص، أو عند عدم العثور على موديله في المكتبة."]],
  ["EQP-17",["يربط كل فتحة بإصدار الموديل والقالب المعتمدين، مع توثيق القرار ونسخة أمر التصنيع.","يسمح بإصدار قص الفتحة المطابقة، ويعيد فتح مراجعتها عند استبدال الجهاز أو الحوض.","يبقى رسم الفتحة مسودة ويُحجز أمر قصها حتى تأكيد التطابق وحسم أي اختلاف بين القالب والجهاز.","٨ · اعتماد التنفيذ لدى المصنع","٩ · التركيب والاستلام","قبل الإفراج عن فتحة تعتمد على موديل، ثم عند مطابقة القطعة الواصلة."]],
  ["CAT-01",["يرتبط كل اختيار برمز الصنف وإصدار الكتالوج الساري عند اعتماده.","عند فتح طلب قديم يسترجع مواصفاته، ويعرض فرق السعر أو القطع عند طلب تحديثه.","يمكن إعداد مسودة باستخدام الكتالوج المتاح. ينتظر تثبيت السعر والمواصفات تحديد الإصدار.","٠ · كتالوج المصنع","١ · فتح المشروع","عند نشر إصدار كتالوج، ويُربط المشروع بالإصدار الذي بدأ به."]],
  ["CAT-02",["قالب يربط نوع الهيكل بأجزائه وبقواعد التجميع والحساب الخاصة به.","اختيار الألواح الملحومة أو القطاعات والحشوات يولّد قائمتَي أجزاء مختلفتين لنفس الحجم الخارجي.","يُحجز حجم الوحدة في المخطط وتبقى قائمة أجزائها معلقة حتى اختيار طريقة البناء.","٠ · كتالوج المصنع","٥ · تفصيل الهيكل وتثبيته","عند تعريف عائلة وحدات جديدة أو اختيار طريقة بنائها في المشروع."]],
  ["CAT-03",["نطاق مسموح وخطوة تعديل لكل بُعد، مع علاقة بين القياس الخارجي والفراغ الداخلي.","يفحص تغيير عمق الصف أو وحدة مفردة ويبيّن أي تجهيز داخلي خرج عن نطاقه.","يُعرض المقاس المقترح للمراجعة. ينتظر إقرار قابلية التصنيع حدود العائلة المعتمدة.","٠ · كتالوج المصنع","٥ · تفصيل الهيكل وتثبيته","عند تحديد نطاق تفصيل العائلة أو تجاوز مقاس مقترح لحدوده."]],
  ["CAT-04",["مقطع ذو اتجاه وأخاديد وسماكات، مرتبط بالإطار والحشوة والوصلة التي يقبلها.","يحدد الفراغ الصافي داخل الإطار، ويختار القطاع الموافق عند حساب الحشوة وقائمة القص.","يستمر التخطيط بالأبعاد الخارجية. تبقى مقاسات الحشوة وأطوال القطاع المتأثرة أولية.","٠ · كتالوج المصنع","٨ · اعتماد التنفيذ لدى المصنع","عند إضافة قطاع جديد أو مراجعة كوده ومقطعه في قائمة الإنتاج."]],
  ["CAT-05",["تربط بطاقة اللوح سماكته واتجاه وجهه وإمكان تدويره بأخدود الإطار وطريقة معالجة الحافة.","يفحص دخول الحشوة في القطاع ويحافظ على اتجاه النقشة عند توزيع القطع على لوح الخام.","يُعرض خيار المادة، ويُعلّق قص الحشوة عند غياب السماكة أو معالجة الحافة ذات الأثر.","٠ · كتالوج المصنع","٦ · اختيار المواد والخامات والألوان","عند تعريف مواد الألواح والحشوات والزجاج فنيًا بالكتالوج، ثم عرض البدائل المتوافقة مع الفتحة والوزن للعميل."]],
  ["CAT-06",["اختيار مرتبط بأجزاء معيّنة، وكود توريد وعينة اعتمدها العميل.","يحدّد أي الدرف تتغير عند استبدال التشطيب وأي كود يطلبه المصنع وبأي كمية.","يُعرض اللون التقريبي. ينتظر طلب التشطيب تحديد كود المورد وحسم أي تعارض مع العينة.","٠ · كتالوج المصنع","٦ · اختيار المواد والخامات والألوان","عند نشر تشطيب مع رمز وعينة في الكتالوج، ثم اختيار العميل لون الواجهة ودرجة لمعانها."]],
  ["CAT-07",["صورة خامة مضبوطة المقياس وخصائص لمعان وملمس تُسند إلى سطوح القطع.","يتغيّر حجم عروق الخشب واتجاهها وانعكاس الضوء في منظور العميل.","يُستخدم لون أو ملمس تقريبي معلن. يستمر حساب القطع متى عُرفت مواصفات المادة.","٠ · كتالوج المصنع","٦ · اختيار المواد والخامات والألوان","عند تجهيز ملفات الخامات الواقعية للصنف، ثم عند محاكاة العينة على الهيكل المثبّت."]],
  ["CAT-08",["ترتبط الدرفة بنموذج هندسي لهيكلها وحشوتها، وحدود وزنها وتقسيمها وتراكبها.","عند توسيع الوحدة يعيد حساب عرض الدرف والفواصل، ويفحص إمكان استخدام درفة واحدة أو أكثر.","يستمر توزيع الوحدات في الغرفة. تنتظر مقاسات الواجهات والمفصلات اعتماد نوع الدرفة.","٠ · كتالوج المصنع","٥ · تفصيل الهيكل وتثبيته","عند تعريف عائلة درف، ثم عند تخصيص تقسيم واجهة الوحدة."]],
  ["CAT-09",["صندوق ذو حيّز تخزين صافٍ وفواصل داخلية، مرتبط بواجهة وسكة وأغراض يختارها العميل.","يفحص هل تدخل حافظة الرز وتُرفع من مكانها، ويعدّل الفواصل عند تغيير استخدامها.","يمكن حفظ الغرض المطلوب. تتأجل مطابقة الحافظة وقص مكونات الدرج حتى تتحدد أبعاده الداخلية.","٠ · كتالوج المصنع","٥ · تفصيل الهيكل وتثبيته","عند إضافة نظام أدراج أو اختيار تقسيمه وارتفاعاته داخل الخزانة."]],
  ["CAT-10",["يربط طول السكة وخلوصها وامتدادها وتعريف حملها بصندوق الدرج والوزن المتحرك.","يختبر خروج الدرج بالقدر اللازم وملاءمة الحمولة طبقًا لما يدخله المورد في تصنيف السكة.","يبقى الدرج في العرض. لا تعتمد سكته أو ثقوبها بناءً على وزن المحتوى وحده.","٠ · كتالوج المصنع","٥ · تفصيل الهيكل وتثبيته","عند تعريف سكة، ثم عند اختبار طولها وحمولتها مع الدرج المختار."]],
  ["CAT-11",["محور ومدى حركة ونقاط تثبيت لآلية مرتبطة بدرفة محددة الوزن والمقاس.","يرسم مسار الدرفة العلوية مثلًا، ويكشف اصطدامها بالسقف أو بمقبض مجاور أثناء الفتح.","تظهر الواجهة مغلقة، وتظل حركة الفتح وثقوب الآلية بانتظار اختيار موديل موثّق.","٠ · كتالوج المصنع","٥ · تفصيل الهيكل وتثبيته","عند اعتماد آلية فتح جديدة أو تركيبها على واجهة محددة."]],
  ["CAT-12",["جزء يضاف إلى الواجهة ببروز واتجاه ونقاط ثقب، أو مجرى يتبع قطاع الهيكل.","يفحص مرور الدرفة عند الزاوية ويحدد ثقوب المقبض أو القطاعات المطلوبة للفتح المدمج.","يمكن إبقاء اقتراح الواجهة. ينتظر تخريمها أو قص مجراها اختيار وسيلة الفتح.","٠ · كتالوج المصنع","٥ · تفصيل الهيكل وتثبيته","عند تعريف نظام المقبض وبروزه لاختبار الحركة. يختار العميل لون القطعة وتشطيبها في المرحلة ٦."]],
  ["CAT-13",["تجهيز محدد الموديل يرتبط بطلب تخزين، وفتحة تركيب، ومساحة سحب وفتح غطاء.","يفحص وضع العيّاشة في وحدة بعينها وفتح غطائها، ويضيف الموديل المختار إلى الطلب.","يبقى طلب تخزين الأرز محفوظًا. إذا اختار العميل كيسه الخاص فلا يلزم موديل عيّاشة.","٠ · كتالوج المصنع","٥ · تفصيل الهيكل وتثبيته","عند توريد عيّاشة أو تجهيز خاص واختيار موديله لطلب عميل."]],
  ["CAT-14",["سلة أو آلية ذات يد وتركيب محددين، يربطها البرنامج بفتحة الركن ومسار حركتها.","يفحص مرور السلة من الباب ودورانها دون اصطدام بالجانب أو بواجهة الوحدة المجاورة.","يُعرض الركن كحيّز تخزين. تتأجل الواجهة وتجهيزاتها المرتبطة حتى يتأكد موديل الآلية ويدها.","٠ · كتالوج المصنع","٥ · تفصيل الهيكل وتثبيته","عند إضافة آلية ركن ومراجعة جهة تركيبها ومسار حركتها."]],
  ["CAT-15",["قطع إنهاء ترتبط بطرف صف أو وجه مكشوف وبحدود الجدار والتعلية وفتحات الصيانة.","يحسب عرض حشوة الطرف وطول الوزرة، ويقسمها عند نقطة وصول يلزم فكها.","يبقى توزيع الصف متاحًا. تُراجع قطع الإنهاء عند غياب موضع التماس أو مجال التشذيب.","٠ · كتالوج المصنع","٥ · تفصيل الهيكل وتثبيته","عند تعريف قطاع الوزرة أو الحشوة أو القفلة أو كورنيش الدولاب. تُثبت أبعاد المقطع وبروزه قبل الهيكل، ويُختار التشطيب واللون بعد تثبيته."]],
  ["CAT-16",["نقاط ارتكاز أو تعليق، لكل منها موضع ومجال ضبط وشروط تحميل مرتبطة بسند محدد.","يقارن منسوب كل رجل بالتعلية والأرض، ويكشف قدمًا خارج سطح الدعم أو خارج مجال الضبط.","يعرض موضع الوحدة أوليًا. يتطلب قبول الارتكاز بيانات الدعامات وسندها الفعلي.","٠ · كتالوج المصنع","٨ · اعتماد التنفيذ لدى المصنع","عند إضافة رجل أو دعامة أو نظام تعليق ثم اعتماد نقاط الارتكاز."]],
  ["CAT-17",["ألواح ترتبط بحدود الوحدات والجدار وفتحات الأجهزة، مع قواعد الحافة والتدعيم والبروز.","يختار مواضع الوصلات الممكنة ويحسب منسوب أسفل السطح الذي يحد فتحة غسالة الصحون.","يمكن عرض شكل السطح. تبقى الوصلات والفتحات والسماكة النهائية قيد مراجعة المورد.","٠ · كتالوج المصنع","٦ · اختيار المواد والخامات والألوان","عند إدخال مواد الأسطح المتوفرة وسماكاتها وحوافها، ثم عند اختيار العميل سطحًا وفحص تأثير سماكته في الهيكل المثبّت."]],
  ["CAT-18",["قالب فتح وتثبيت خاص بموديل التجهيز ومادة السطح وسماكته.","يحسب فتحة الحوض أو الموقد من القالب، ويفحص تعارض جسمه أو مثبتاته مع حواف الوحدة.","يمكن اختيار مكان تقريبي للتجهيز. ينتظر قص الفتحة قالب الموديل المعتمد.","٠ · كتالوج المصنع","٥ · تفصيل الهيكل وتثبيته","عند إضافة قالب تثبيت تجهيز، ثم عند مطابقته بموديل الحوض أو الموقد."]],
  ["CAT-19",["علاقات مشروطة بين القطع الأصلية والبدائل، مع أثر البديل في المقاس واللون والوظيفة.","عند نفاد سكة يعرض البدائل المتوافقة، ويبيّن ما يتغير في الدرج والثقوب قبل الاستبدال.","يظل الصنف الأصلي على الطلب. يراجع المصنع أي بديل قبل إدخاله في قائمة الشراء أو القص.","٠ · كتالوج المصنع","٥ · تفصيل الهيكل وتثبيته","عند تحديث توافق القطع أو استبدال إكسسوار داخل وحدة."]],
  ["MFG-01",["وصفة تربط كل جزء بالوحدة وبكميته ومصدره، مع تمييز المصنّع والمشترى وما يورده العميل.","تجمع القطع المشتركة للشراء وتحدد القطع المطلوب قصها لكل وحدة وتمنع احتساب جهاز العميل ضمن مشتريات المصنع.","تبقى رسمة الوحدة متاحة، وتسجّل البنود الناقصة قبل اعتماد إجمالي الكميات والتكلفة.","٠ · كتالوج المصنع","٨ · اعتماد التنفيذ لدى المصنع","عند تعريف مكونات عائلة، ثم عند توليد قائمة مواد الوحدات المعتمدة."]],
  ["MFG-02",["علاقة بين مقاس التصميم وطول القطعة بعد خصومات الوصلات، مع مرجع الطرف الطويل أو القصير.","عند تعديل عرض الوحدة يعيد حساب أطوال القطاعات وزوايا طرفيها على قائمة القص.","تُستخرج أسماء القطع وكمياتها المعروفة. تبقى أطوال القص التي لا تملك معادلة معتمدة معلّقة.","٠ · كتالوج المصنع","٨ · اعتماد التنفيذ لدى المصنع","عند إعداد معادلات القص، ثم قبل إصدار أطوال القطع للمشروع."]],
  ["MFG-03",["علاقة تلاقي بين قطعتين تحمل نوع الوصلة واتجاهها وتداخلها وموصلاتها.","يحسب أثر الوصلة في طول القطعتين وعدد الزوايا المطلوبة ويحدد ترتيب تجميع الإطار.","يظهر الإطار إجمالًا. تنتظر نهايات القطع والموصلات تأكيد طريقة التلاقي.","٠ · كتالوج المصنع","٨ · اعتماد التنفيذ لدى المصنع","عند توثيق نظام وصل، ثم عند تدقيق التقاء القطاعات وزوايا القص."]],
  ["MFG-04",["عمليات مرتبطة بوجه القطعة ومحور الصفر والأداة أو الإكسسوار الذي تتطلبه.","تولّد إحداثيات ثقب السكة أو المفصلة، ومسار التفريز أو أبعاد الفرد عند استخدام صاج مثني.","يمكن إصدار تفاصيل الأجزاء المكتملة. تبقى عمليات القطعة التي يجهل مرجعها أو تعويض ثنيها قيد المراجعة.","٠ · كتالوج المصنع","٨ · اعتماد التنفيذ لدى المصنع","عند تجهيز عمليات تثقيب أو تفريز أو ثني للصنف المختار."]],
  ["MFG-05",["يرتبط كل مستهلك بموصل أو حافة أو طول تركيب، وبالخامات الصالحة للاستخدام معه.","يحصي براغي مواضع التثبيت ومواد إحكام الحواف ويضيفها إلى تجهيزات التركيب.","تظل الكميات غير المعروفة خارج الإجمالي المؤكد، وتُستكمل قبل تجهيز مجموعة التركيب المتأثرة.","٠ · كتالوج المصنع","٨ · اعتماد التنفيذ لدى المصنع","عند تعريف مواد التركيب والعزل ثم حصر المستهلكات المطلوبة للطلب."]],
  ["MFG-06",["دفعات أعواد وألواح بأبعادها، مع عرض أثر الشفرة وهوامش التثبيت واتجاه القطع.","يوزّع قطع الواجهات والقطاعات على الخام ويحسب عدد الأعواد أو الألواح والبواقي القابلة للاستعمال.","تبقى أبعاد القطع النهائية معروفة، بينما ينتظر عدد وحدات الخام والهدر خطة قص مناسبة.","٠ · كتالوج المصنع","٨ · اعتماد التنفيذ لدى المصنع","عند إدخال أطوال الخام وفاقد المنشار، ثم عند إعداد خطة القص."]],
  ["MFG-07",["لكل موضع حرج حدود انحراف وخلوص وتركيب ومجال ضبط مرتبطة بمرجع فني.","يفحص هل يكفي فراغ التركيب بعد احتساب اختلاف القياس والتصنيع، خصوصًا بين جدارين.","يمكن إظهار التطابق الاسمي. لا يعتمد المقاس الحرج للقص حتى تتحدد سماحاته ويؤكد قياسه.","٠ · كتالوج المصنع","٨ · اعتماد التنفيذ لدى المصنع","عند اعتماد سماحات النظام ثم فحص الأبعاد الحساسة قبل القص."]],
  ["MFG-08",["ترتبط العملية بآلة وأداة وحدود تثبيت ومحوّل ملفات وإصدار صيغة تشغيل.","يختار مسار التشغيل المناسب ويصدر ملف الماكينة بعد التحقق من اتجاه المحاور والأداة.","تبقى قائمة القطع والرسومات مفيدة للورشة. يتوقف ملف التشغيل الآلي لتلك الآلة حتى التحقق من الربط.","٠ · كتالوج المصنع","٨ · اعتماد التنفيذ لدى المصنع","عند تسجيل آلة أو صيغة تشغيل، ثم عند إرسال عملية متوافقة لها."]],
  ["MFG-09",["أسعار ذات وحدة وفترة سريان ترتبط بكميات القطع والمواد والخدمات المشمولة بالعرض.","يحدّث فرق سعر البديل ويجمّع المواد والتشغيل والتركيب وفق القواعد التجارية المسجلة.","يستمر فحص التصميم. يعرض البنود غير المسعّرة ولا يصدر سعرًا نهائيًا يشملها حتى تستكمل.","٠ · كتالوج المصنع","٧ · مراجعة العرض واعتماد العميل","عند تحديث الأسعار والتكاليف، ثم تثبيت أسعار عرض العميل."]],
  ["MFG-10",["لكل صنف رصيد متاح بعد الحجز، ومصدر شراء ومدة توريد وتاريخ آخر تحديث.","يقارن كمية الطلب بالمتاح ليحدد مقدار الشراء وأثر النقص في موعد التنفيذ.","يمكن اعتماد الصلاحية الهندسية للصنف. تتأجل وعود الكمية وموعد التسليم حتى تحديث التوفر.","٠ · كتالوج المصنع","٨ · اعتماد التنفيذ لدى المصنع","عند تحديث رصيد صنف أو مهلة توريده، ثم عند حجز مواد الدفعة."]],
  ["MFG-11",["نطاق عمل مرتبط بمورد وبجزء من الطلب، مع الرسمة وموعد القياس أو التسليم ومسؤول كل خطوة.","يعزل الجزء الخارجي في أمر شراء ويضبط موعد تصنيعه وتوريده مع تركيب الوحدات.","يتابع المصنع البنود الداخلية المستقلة. يُبقي سعر العمل الخارجي وموعده مشروطين بعرض المورد.","٨ · اعتماد التنفيذ لدى المصنع","٧ · مراجعة العرض واعتماد العميل","عند وجود سطح أو عمل من مورد خارجي يتطلب مطابقة العرض ومواصفة التوريد."]],
  ["MFG-12",["نتيجة فحص تربط عينة فعلية برسمة إصدار محدد وبقياسات وحركات تحقق منها فريق الجودة.","يطابق أول قطعة مصنعة مع النموذج ويحدد هل تعتمد عائلة جديدة أو تحتاج تعديلًا قبل التكرار.","يجوز تجربة التصميم. يبقى تعميم طريقة البناء الجديدة على الدفعة رهن فحص العينة حسب خطة الجودة.","٠ · كتالوج المصنع","٨ · اعتماد التنفيذ لدى المصنع","عند تأهيل عائلة تصنيع بعينة، ثم مقارنة أوامر الطلب بمعيار الفحص."]],
  ["MFG-13",["بند مستقل في مشروع العميل، مرتبط برسم خاص ومواد وتكلفة وحالة اعتماد.","يحجز مكان القطعة ويضيفها إلى العرض وقائمة التصنيع بعد اعتماد طريقة بنائها وسعرها.","يحفظ طلب العميل ومكانه المقترح. توسم القطعة الخاصة قيد الدراسة حتى يعتمد المصنع تفاصيلها.","٥ · تفصيل الهيكل وتثبيته","٨ · اعتماد التنفيذ لدى المصنع","عند طلب قطعة خاصة خارج الكتالوج، ثم عند اعتماد رسمها وطريقة تصنيعها."]],
  ["DES-01",["ترتبط الحدود المسموح وضع الخزائن فيها بجدار أو جزء من الأرض، مع مصدر الحجز ونوع الوحدة.","يبحث عن توزيع داخل الأجزاء الصالحة فقط، ويفحص حيز الفتح والمرور والخدمة عند الحاجة. لا يكرر خصم عائق مُمثَّل في طرف المقطع أو صافي عمقه.","يستمر التوزيع اليدوي في المناطق المعروفة، ويُعلَّق الحكم على الموضع الذي لم تتحدد حدوده.","٤ · اختيار التوزيع","٥ · تفصيل الهيكل وتثبيته","عند توليد توزيع أو تعديل منطقة يسمح فيها بوضع الخزائن أو يُمنع."]],
  ["DES-02",["يرتبط كل باب بمحور فتحه والدرج بمسار سحبه، مع مساحة المرور والأجزاء المطلوب فتحها معًا.","يفحص مسار الحركة كاملًا ويُظهر الجزء المصطدم، مثل مقبض دولاب يعوق باب غسالة الصحون قبل اكتمال فتحه.","يعرض الأجزاء وهي مغلقة، ويُبقي اختبار الحركة المتأثر غير مكتمل إلى أن تُعرف الأبعاد والآلية.","٤ · اختيار التوزيع","٥ · تفصيل الهيكل وتثبيته","عند اختبار ممرات التوزيع، ثم بعد تثبيت موديل فتح أو سحب محدد."]],
  ["DES-03",["لكل شرط مرجع وإصدار وحالة انطباق ونوع تركيب. تُربط قيمة الخلوص أو التهوية بموديل الجهاز.","يقارن الفتحة والتهوية المتاحتين بما يتطلبه الموديل، ويحيل الحالات التي تحتاج حكمًا مهنيًا إلى المختص.","يظل موضع الجهاز مبدئيًا عند غياب شرط حاسم، ويُعلّق اعتماد فتحته حتى تُراجع تعليمات الموديل والمرجع المنطبق.","٠ · كتالوج المصنع","٨ · اعتماد التنفيذ لدى المصنع","عند توثيق قاعدة تركيب من دليل موديل أو مرجع مختص وعند مطابقتها بالمشروع."]],
  ["DES-04",["يرتبط محور المحاذاة ونمط التقسيم بمجموعة درف، وتُحفظ الاستثناءات والواجهات المثبّتة منفصلة.","يرتّب تقسيم الواجهات بحيث تلتقي الفواصل أو تتماثل حسب اختيار العميل، ويميّز الخيارات التي تتطلب تغيير تقسيم مثبت.","إذا فُوّض الشكل للمصمم، يعرض البرنامج عدة تقسيمات ممكنة حتى يختار العميل مظهر الواجهة.","٥ · تفصيل الهيكل وتثبيته","٦ · اختيار المواد والخامات والألوان","عند تثبيت المحاذاة والمقاسات وخطوط فواصل الدرف، ثم تعيين تشطيباتها وألوانها بعد التثبيت."]],
  ["DES-05",["لكل معيار وحدة وطريقة حساب وأولوية، مثل أطول سطح تحضير متصل بعد استبعاد الحوض والموقد.","يحسب الفرق بين تصميمين ويُظهر للعميل ماذا يكسب من سطح أو تخزين، ومقابل أي فرق في السعر.","يعرض المعايير التي لها بيانات. إذا غاب سعر أحد البدائل، تبقى مقارنته المالية معلقة وتظل المقارنة المكانية متاحة.","٤ · اختيار التوزيع","٧ · مراجعة العرض واعتماد العميل","عند توفر بديلين قابلين للمقارنة أو تغير السعر بعد التفصيل."]],
  ["DES-06",["تُحفظ زاوية الكاميرا وارتفاعها وإعدادات الإضاءة للمشهد وتُربط الخامات بعينات من كتالوج المصنع.","يعرض البديلين من الزاوية والإضاءة نفسيهما، فيستطيع العميل عزل أثر تغيير اللون أو التشطيب.","تبقى المخططات والأبعاد صالحة للاستخدام، ويُعرض منظور تقريبي إلى أن تتوفر العينة أو الصورة المرجعية.","٦ · اختيار المواد والخامات والألوان","٧ · مراجعة العرض واعتماد العميل","بعد اختيار الخامات عند ضبط الإضاءة والمنظور، ثم مقارنة البدائل من الزاوية نفسها عند عرضها على العميل."]],
  ["DES-07",["يرتبط الاسم الحر بالعنصر وبنوع قيمة ووحدة ومصدر، مع قاعدة توافق أو تسعير إذا اعتمدها المصنع.","يظهر الطلب في المشروع، ويدخل في الحسابات المحددة له عند تعريف قاعدة، مثل التحقق من ارتفاع دلة خاصة ورفّها.","يحتفظ البرنامج بالطلب ويظهره للمصمم. ينتظر التحقق الآلي أو التسعير الخاص تعريف القاعدة أو عرض المصنع.","٥ · تفصيل الهيكل وتثبيته","٣ · احتياجات العميل وأجهزته","عند ذكر خاصية لا يغطيها الكتالوج، أو عند تحويلها إلى تفصيل قابل للفحص."]],
  ["INS-01",["سلسلة مداخل ومنعطفات ومصعد تقارن بغلاف القطعة أو الحزمة أثناء المناولة.","يكشف حاجة سطح الجزيرة أو الخزانة الطويلة إلى تقسيم أو تجميع في الموقع قبل التصنيع.","يستمر تخطيط المطبخ. تُراجع القطع كبيرة الحجم قبل اعتماد قصها أو شحنها قطعة واحدة.","٢ · رفع الغرفة والخدمات","٨ · اعتماد التنفيذ لدى المصنع","عند رفع أضيق ممر أو مصعد أو مدخل، ثم قبل إصدار قطعة كبيرة للنقل."]],
  ["INS-02",["تثبت الوحدة إلى جدار أو نقطة أصل باتجاه وارتفاع، وترتبط بجاراتها ومعرّفها في الطلب.","يولّد موضعها في مخطط التركيب ويحدد أي جنب مكشوف وأي وصلات ستتغير عند نقلها.","تظل الوحدة قابلة للتخصيص منفردة. تنتظر رسمة تركيبها وواجهات نهايات الصف تثبيت موضعها.","٨ · اعتماد التنفيذ لدى المصنع","٩ · التركيب والاستلام","عند ترقيم الوحدات وربط مواضعها بمخطط التركيب المعتمد."]],
  ["INS-03",["مواضع تثبيت معتمدة تقارن بسند الجدار ومناطق الحظر ومسارات الخدمات الموثقة.","يعرض نقاط التعليق الممكنة ويطلب تعديل التثبيت إذا صادف مسار خدمة أو سندًا غير مناسب.","تُعرض الخزانة العلوية في التصميم. يبقى ثقب الجدار وتعليقها بانتظار فحص السند والموقع.","٢ · رفع الغرفة والخدمات","٩ · التركيب والاستلام","عند رفع الجدار وموانع التثبيت، ثم التحقق من جاهزيته قبل التعليق."]],
  ["INS-04",["كل تغيير مطلوب يسجّل بموقع حالي ومستهدف وحالة تنفيذ، ويرتبط بالوحدات التي تعتمد عليه.","يعرض بديل نقل الصرف أو المقبس، ويميّزه عن الموقع المؤكد إلى حين إتمام العمل وإعادة القياس.","يمكن عرض البديل المشروط. لا تعتمد الفتحات المتوقفة على النقل إلى أن يؤكد المسؤول التنفيذ.","٤ · اختيار التوزيع","٨ · اعتماد التنفيذ لدى المصنع","عند اقتراح أعمال موقع مسبقة، ثم قبل إطلاق دفعة تعتمد على إنجازها."]],
  ["INS-05",["قالب مؤرخ لحدود السطح المركّب يربط فتحاته بالموديلات النهائية وإصدار الرسم المعتمد.","يولّد حدود قص السطح الفعلية، ويفصلها عن التقدير المبكر المستعمل في العرض.","يمكن إكمال الوحدات المستقلة. يُعلّق قص السطح أو الفتحة المتأثرة حتى يراجع المورد قالبها.","٩ · التركيب والاستلام","٨ · اعتماد التنفيذ لدى المصنع","عند اكتمال تركيب القواعد، ويُعاد القالب إلى المصنع لإذن قصّ السطح."]],
  ["INS-06",["نسخة مؤرخة تشمل الأصناف والاختيارات المثبتة والسعر الذي وافق عليه العميل.","يثبت نسخة العرض ويقارن ما يستجد من بدائل بها دون تمرير تغيير غير معتمد إلى طلب العميل.","يستمر استكشاف البدائل كمسودات. تبقى موافقة العميل معلقة، واعتماد الورشة للتصنيع إجراء مستقل.","٧ · مراجعة العرض واعتماد العميل","٨ · اعتماد التنفيذ لدى المصنع","عند اعتماد العميل نسخة التصميم والسعر وربطها بطلب التصنيع."]],
  ["INS-07",["سجل فرق يربط النسخة السابقة واللاحقة بالقطع المتأثرة وبما اشتُري أو قُص بالفعل.","يكشف ما يحتاج إعادة تسعير أو تعديل أمر شراء أو إعادة قص، ويعيد البنود المتأثرة إلى المراجعة.","تظل النسخة المعتمدة مرجعًا. تُعلّق القطع التي قد يتلفها التغيير حتى تُحسم تعليمات التنفيذ.","٧ · مراجعة العرض واعتماد العميل","٨ · اعتماد التنفيذ لدى المصنع","عند طلب تعديل بعد الاعتماد التجاري أو الفني، مع عرض أثره وإصدار نسخة جديدة."]],
  ["INS-08",["حالة إفراج لكل قطعة أو دفعة مرتبطة برسمة محددة وقياسات وموديلات مؤكدة وتوقيع الورشة.","يصدر أمر الإنتاج للبنود المفرج عنها ويُظهر السبب المسؤول عن تعليق كل بند آخر.","يبقى العرض المعتمد للعميل محفوظًا. لا يُرسل أمر قص للقطعة التي ما زالت بياناتها أو موافقتها ناقصة.","٨ · اعتماد التنفيذ لدى المصنع","٩ · التركيب والاستلام","قبل إطلاق كل دفعة تصنيع، وعند رفع المانع عن دفعة كانت معلقة."]],
  ["INS-09",["سجل استلام يربط قطعة العميل الفعلية بموديلها وأبعادها وبالأجزاء المنتظرة لها.","يكشف اختلاف الموديل المستلم عن المرسوم، ويفصل الأعمال الجاهزة عن دفعة الفتحات المتأثرة.","تتابع القطع المستقلة مسارها. تُؤجّل الفتحات التي تشترط مطابقة القطعة الفعلية حتى الاستلام والفحص.","٨ · اعتماد التنفيذ لدى المصنع","٩ · التركيب والاستلام","عندما تتوقف دفعة على وصول حوض أو جهاز أو قطعة يوردها العميل."]],
  ["INS-10",["تجمع القطع في حزم مرتبطة برقم الوحدة ومرحلة التركيب وحدود المناولة.","يطبع بطاقات الحزم ويحدد أسبقية تحميل القطع وتسليمها حسب ترتيب تركيب الموقع.","تظل قائمة التصنيع صالحة. ينتظر تجهيز الشحنة تحديد حزم القطع الكبيرة وترتيب وصولها.","٨ · اعتماد التنفيذ لدى المصنع","٩ · التركيب والاستلام","عند تجهيز الطلب للشحن وتحديد ترتيب دخول الوحدات وتركيبها."]],
  ["INS-11",["اختبارات تسليم مرتبطة بعنصر محدد، مثل فتح الشباك أو الوصول إلى المحبس، مع المسؤول والنتيجة.","يسجّل التعارض أو النقص على الوحدة المعنية ويحدد ما يلزم إصلاحه قبل إقفال بند الاستلام.","يمكن تسليم البنود المختبرة وفق الاتفاق. يبقى بند الحركة أو الوصول غير المختبر مفتوحًا.","٩ · التركيب والاستلام","—","عند تسليم المطبخ واختبار الفتح والتشغيل وتسجيل ما يحتاج متابعة."]],
  ["COR-01",["يربط الركن بجدارين مسمّيين وبزاوية مقاسة، فيظل معنى أ وب ثابتًا عند تدوير المنظور.","يختار العميل تجهيز ركن واحد أو كليهما بحلّين مختلفين، ويرسم المصمم كل تقاطع بزاويته الفعلية.","تُعرض زاوية مبدئية محددة الحالة، وتؤجّل مقاسات القص المتأثرة لحين التحقق من الرفع.","٢ · رفع الغرفة والخدمات","٤ · اختيار التوزيع","عند تحديد تقاطع الجدارين وقياس زاويته، ثم عند اقتراح استغلال الركن."]],
  ["COR-02",["يحفظ حدود المساحة المشغولة على الضلعين لكل صف مع توحيد مساحة التداخل في الركن.","يحسب ما يتبقى من كل جدار للخزائن التالية، ويختبر مزاحمة جهاز أو فتحة قريبة عند تغيير طول أو عمق.","يُترك الضلع غير المقاس مبدئيًا، ويؤجّل اعتماد توزيع الوحدات المجاورة على هذا الضلع.","٤ · اختيار التوزيع","٥ · تفصيل الهيكل وتثبيته","عند اختيار إشغال ضلع أو ضلعين، ثم ضبط الأطوال والأعماق لكل ضلع."]],
  ["COR-03",["يُحفظ شغل الركن في كل نطاق ارتفاع، أو كوحدة متصلة ذات حدود سفلية وعليا. للخزائن المجاورة حدود منفصلة.","ينهي الصف العلوي عند الحد الذي اختاره العميل أو يوصله، ويحسب الارتفاعات والواجهات وانقطاع السطح بحسب الحل.","يمكن مواصلة السفلي عند حسمه، وتبقى تفاصيل الجزء الرأسي غير المحسوم معروضة كاختيار مفتوح.","٤ · اختيار التوزيع","٥ · تفصيل الهيكل وتثبيته","عند اختيار ركن سفلي أو علوي أو طويل، ثم ضبط مناسيب كل طبقة."]],
  ["COR-04",["يعرّف أجسام الخزائن وحجرات التخزين والفواصل ضمن المساحة نفسها. قد تصل فتحتان إلى حجرة واحدة.","يحسب الحيز القابل للاستعمال وعدد الأجسام والألواح، ويميز الركن المحجوب من مساحة التخزين الفعلية.","تبقى حدود الركن معروفة، ويؤجّل حساب سعته وقائمة ألواحه حتى يعتمد المصنع طريقة التجميع.","٥ · تفصيل الهيكل وتثبيته","٨ · اعتماد التنفيذ لدى المصنع","عند تقسيم الركن إلى حيز مشترك أو حجرات، ثم مراجعة الحواجز والوصلات."]],
  ["COR-05",["تتبع كل فتحة واجهة محددة وحجرة محددة. يحفظ عرضها الصافي بعد الحشوات والقوائم والتجهيزات.","يتحقق من جهة الوصول ومن مرور الغرض من الفتحة. يمكن لركن يشغل جدارين أن يحمل واجهة دخول واحدة فقط.","يمكن توزيع الكتل، ويظل نموذج الدرفة وتركيب الإكسسوار واختبار الوصول قيد المراجعة.","٥ · تفصيل الهيكل وتثبيته","٨ · اعتماد التنفيذ لدى المصنع","عند اختيار وجهة الوصول وواجهة الركن، ثم تدقيق صافي الفتحة."]],
  ["COR-06",["يُربط كل جزء متحرك بمحور دوران أو مسار سحب، وبالدرفة الأخرى عند اقتران حركتيهما.","يفحص مسار الواجهة قرب مقابض الجوار وغسالة الصحون، ويحدّد المفصلات أو السكك الخاصة بالتكوين المختار.","يمكن اعتماد جهة الوصول مبدئيًا وتبقى خلوصات التشغيل وتجهيز ثقوب العتاد معلّقة.","٥ · تفصيل الهيكل وتثبيته","٨ · اعتماد التنفيذ لدى المصنع","عندما يحدد العميل طريقة فتح الركن، ثم عند تأكيد مفصلته ومسارها."]],
  ["COR-07",["ترتبط متطلبات الاستخدام بالحجرة والطبقة وموضعهما، ويُحفظ الغرض مستقلًا عن الإكسسوار.","يفاضل بين رف مكشوف أو ثابت أو قابل للسحب حسب الوصول والحجم، ويحفظ الغرض المثبّت عند إعادة التوزيع.","تبقى الوحدة قابلة للتصميم، ويؤجّل الحكم على ملاءمتها لغرض بعينه حتى تتوفر مقاساته وطريقة استخدامه.","٣ · احتياجات العميل وأجهزته","٥ · تفصيل الهيكل وتثبيته","عندما يذكر العميل وظيفة للركن، ثم عند تخصيصها لركن وطبقة محددين."]],
  ["COR-08",["يميز البرنامج بين رغبة العميل وموديل الإكسسوار، ويسجل هل تتحرك المستويات مستقلة أم كوحدة واحدة.","يستخرج عدد الرفوف أو السلال والعتاد والسعر من الاختيار الفعلي، ويحدد أي حيز داخلي يتبقى بعد تركيبه.","تظل رغبة التخزين محفوظة. يبقى سعر الآلية وفتحات تثبيتها مبدئيين لحين تحديد موديل أو تفصيل معتمد.","٥ · تفصيل الهيكل وتثبيته","٨ · اعتماد التنفيذ لدى المصنع","عند اختيار رف أو درج أو سلة لكل طبقة وربطها بموديلها."]],
  ["COR-09",["يقارن متطلبات الموديل بأبعاد التركيب ثم يختبر جسم الآلية والغرض المخزَّن عبر تتابع الحركة.","يكشف سلة تدخل في الخزانة ولا تخرج من بابها، أو رفًا يدور بينما يصطدم القدر بالإطار، فيقترح تعديلًا محددًا.","يمكن اعتماد المظهر عند رغبة العميل، ويؤجّل اختيار الآلية للطلب وتجهيز ثقوبها حتى تُحسم القيود المؤثرة.","٥ · تفصيل الهيكل وتثبيته","٨ · اعتماد التنفيذ لدى المصنع","عند تجربة آلية الركن داخل النموذج، ثم التأكد منها قبل قصّ الوحدة."]]
]);
